class Solution {
public:
    int count = 0;
    void walk(TreeNode* node, int best) {
        if (!node) return;
        if (node->val >= best) count++;
        best = max(best, node->val);
        walk(node->left, best);
        walk(node->right, best);
    }
    int goodNodes(TreeNode* root) {
        walk(root, INT_MIN);
        return count;
    }
};
